  window.pwsToggleTodo = function pwsToggleTodo(checkbox, activityLabel) {
    var schedule = _dayData && _dayData.finalSchedule ? _dayData.finalSchedule.filter(function(s){ return s.ownsIt !== false; }) : [];
    var item = schedule.filter(function(s){ return s.label === activityLabel; })[0];
    if (item) item._todoChecked = checkbox.checked;
    var row = checkbox.parentNode;
    if (row) { var txt = row.querySelector('.pws-todo-text'); if (txt) { if (checkbox.checked) txt.classList.add('checked'); else txt.classList.remove('checked'); } }
  };

  window.pwsCheckin = function pwsCheckin(idx, result) {
    if (idx < 0) return;
    if (!_dayData || !_dayData.finalSchedule) return;
    var schedule = _dayData.finalSchedule.filter(function(s) { return s.ownsIt !== false && !_isSkipped(s.label || ''); });
    var item = schedule[idx]; if (!item) return;
    item._checkedIn = result;
    if (!item.id) pwsEnsureSlotIds_(_dayData.finalSchedule); /* v91_8: mid-session slots get their stone before the record is carved */
    pwsSaveDaySchedule();
    post({ action: 'pwsLogAdherence', sessionId: _session, requestingMemberId: _memberId,
      date: pwsLocalDate(), windowKey: item.id || ('label_' + (item.label || ('window_' + idx)).replace(/\s+/g, '_').toLowerCase()),
      activityLabel: item.label || ('window_' + idx), completed: result === 'done', note: '', lawTag: pwsLawTagFromSlot(item) });
    pwsRenderDayTile();
    pwsBehavioralCascade(item, result, schedule);
    var allChecked = schedule.filter(function(s) { return s._checkedIn; });
    var doneCount = schedule.filter(function(s) { return s._checkedIn === 'done'; }).length;
    if (allChecked.length === schedule.length) pwsAdherenceFeedback(doneCount, schedule.length);
  };

  window.pwsCheckinByLabel = function pwsCheckinByLabel(label, result, note, quiet) {
    /* v91_11: optional note rides the adherence row (the fire reading lands
       here as 'devotion: N/5'); optional quiet skips the tile re-render so
       an in-row follow-on (the choke fork) survives. Both default off --
       every existing caller is untouched in behavior. */
    if (window.FindME && window.FindME.chime && result) { window.FindME.chime('done'); }
    if (!_dayData || !_dayData.finalSchedule) return;
    var schedule = _dayData.finalSchedule.filter(function(s) { return s.ownsIt !== false && !_isSkipped(s.label || ''); });
    var item = null;
    var idx = -1;
    for (var i = 0; i < schedule.length; i++) {
      if (schedule[i].label === label) { item = schedule[i]; idx = i; break; }
    }
    if (!item) return;
    item._checkedIn = result;
    if (!item.id) pwsEnsureSlotIds_(_dayData.finalSchedule); /* v91_8: the stone before the record */
    pwsSaveDaySchedule();
    post({ action: 'pwsLogAdherence', sessionId: _session, requestingMemberId: _memberId,
      date: pwsLocalDate(), windowKey: item.id || ('label_' + (item.label || ('window_' + idx)).replace(/\s+/g, '_').toLowerCase()),
      activityLabel: item.label || ('window_' + idx), completed: result === 'done', note: note || '', lawTag: pwsLawTagFromSlot(item) });
    if (!quiet) pwsRenderDayTile();
    pwsBehavioralCascade(item, result, schedule);
    var allChecked = schedule.filter(function(s) { return s._checkedIn; });
    var doneCount = schedule.filter(function(s) { return s._checkedIn === 'done'; }).length;
    if (allChecked.length === schedule.length) pwsAdherenceFeedback(doneCount, schedule.length);
  };

  /* v91_11 THE FIRE READING (founder's design, 8/26): DONE on Talent Time
     blooms a 1-5 devotion strip -- "the fire of the cascade." The rating
     rides the stone's adherence row as note 'devotion: N/5'. 3-5: the fire
     stands, check-in lands, strip folds. 1-2: the check-in logs quietly and
     the story begins -- "What's choking it -- no time, or no pull?"
     NO TIME -> the Responsibility realm, Bruno's bench (/todos#forge).
     NO PULL -> Doc B, with the founder's transition beat ("I see... Bruno?
     Hmmm... let me check with the Doc...") and ONE generated 4-LAWS
     question, warm and accepting. A dead wire never fails silent: if the
     generation errs, a canned question stands in (house rule v104.1). */
  window.pwsTalentFire = function pwsTalentFire(btn, label) {
    var row = btn && btn.parentNode ? btn.parentNode : null; if (!row) return;
    var host = row.parentNode; if (!host) return;
    var oldStrip = host.querySelector('.pws-fire-strip');
    if (oldStrip && oldStrip.parentNode) oldStrip.parentNode.removeChild(oldStrip);
    var es = (_lang === 'es');
    var strip = document.createElement('div');
    strip.className = 'pws-fire-strip';
    strip.setAttribute('onclick', 'event.stopPropagation();');
    strip.style.cssText = 'margin-top:8px;padding:10px 12px;border:1px solid rgba(200,168,75,0.35);border-radius:4px;background:rgba(200,168,75,0.05);';
    var q = document.createElement('div');
    q.style.cssText = 'font-family:Cormorant Garamond,serif;font-size:18px;font-style:italic;color:rgba(240,230,204,0.85);margin-bottom:8px;';
    q.textContent = es ? '\u00bfCu\u00e1nto le diste hoy a crear? (1\u20135)' : 'How much did you give to creating today? (1\u20135)';
    strip.appendChild(q);
    var btnRow = document.createElement('div');
    btnRow.style.cssText = 'display:flex;gap:8px;';
    function mkNum(n) {
      var b = document.createElement('button');
      b.textContent = String(n);
      b.style.cssText = 'flex:1;min-height:44px;font-family:Cinzel,serif;font-size:17px;color:#c8a84b;background:transparent;border:1px solid rgba(200,168,75,0.45);border-radius:4px;cursor:pointer;';
      b.onclick = function(ev) { if (ev && ev.stopPropagation) ev.stopPropagation(); pwsFireRated_(strip, label, n); };
      return b;
    }
    for (var fn = 1; fn <= 5; fn++) btnRow.appendChild(mkNum(fn));
    strip.appendChild(btnRow);
    host.insertBefore(strip, row.nextSibling);
  };

  function pwsFireRated_(strip, label, n) {
    var es = (_lang === 'es');
    if (n >= 3) {
      /* The fire stands. Normal check-in; the re-render folds the strip. */
      pwsCheckinByLabel(label, 'done', 'devotion: ' + n + '/5');
      return;
    }
    /* Low fire: log quietly so the fork survives, then begin the story. */
    pwsCheckinByLabel(label, 'done', 'devotion: ' + n + '/5', true);
    strip.innerHTML = '';
    var q2 = document.createElement('div');
    q2.style.cssText = 'font-family:Cormorant Garamond,serif;font-size:18px;font-style:italic;color:rgba(240,230,204,0.85);margin-bottom:8px;';
    q2.textContent = es ? '\u00bfQu\u00e9 lo est\u00e1 ahogando \u2014 falta de tiempo, o falta de atracci\u00f3n?' : 'What\u2019s choking it \u2014 no time, or no pull?';
    strip.appendChild(q2);
    var fRow = document.createElement('div');
    fRow.style.cssText = 'display:flex;gap:8px;';
    function mkFork(txt, fn2) {
      var b = document.createElement('button');
      b.textContent = txt;
      b.style.cssText = 'flex:1;min-height:44px;font-family:Cinzel,serif;font-size:14px;letter-spacing:0.1em;color:#c8a84b;background:transparent;border:1px solid rgba(200,168,75,0.45);border-radius:4px;cursor:pointer;';
      b.onclick = function(ev) { if (ev && ev.stopPropagation) ev.stopPropagation(); fn2(); };
      return b;
    }
    fRow.appendChild(mkFork(es ? 'SIN TIEMPO' : 'NO TIME', function() { pwsFireNoTime_(strip, n); }));
    fRow.appendChild(mkFork(es ? 'SIN ATRACCI\u00d3N' : 'NO PULL', function() { pwsFireNoPull_(n); }));
    strip.appendChild(fRow);
  }

  function pwsFireNoTime_(strip, n) {
    var es = (_lang === 'es');
    strip.innerHTML = '';
    var msg = document.createElement('div');
    msg.style.cssText = 'font-family:Cormorant Garamond,serif;font-size:18px;font-style:italic;color:rgba(240,230,204,0.85);';
    msg.textContent = es ? 'Al reino de la Responsabilidad \u2014 el banco de Bruno\u2026' : 'To the Responsibility realm \u2014 Bruno\u2019s bench\u2026';
    strip.appendChild(msg);
    setTimeout(function() { window.location.href = '/todos#forge'; }, 1100);
  }

  function pwsFireNoPull_(n) {
    var es = (_lang === 'es');
    pwsRenderDayTile();
    var ov = document.getElementById('pwsDocBOverlay'); if (ov) ov.classList.add('open');
    var trans = es ? 'Ya veo\u2026 \u00bfBruno? Hmmm\u2026 d\u00e9jame consultar con el Doc\u2026' : 'I see\u2026 Bruno? Hmmm\u2026 let me check with the Doc\u2026';
    pwsAppendBubble(trans, 'docb');
    _docbHistory.push({ role: 'assistant', content: trans });
    var fireSys = 'You are Doc B -- Dr. Eduardo Bustamante, licensed clinical psychologist, creator of the 4 LAWS (Talent, Respect, Responsibility, Limits; Talent rests on the laws beneath it).' +
      ' A member just rated their devotion to their talent project ' + n + ' out of 5 and said the block is loss of attraction -- the fire losing its pull -- not lack of time.' +
      ' Open with exactly ONE warm, smart, encouraging question grounded in the 4 LAWS that helps them explore what dimmed the pull. Accepting tone, no lecture, no diagnosis, 1-2 sentences.' +
      ' Respond in ' + (es ? 'Spanish' : 'English') + '.';
    var fallbackQ = es
      ? 'Cu\u00e9ntame \u2014 cuando el proyecto todav\u00eda te llamaba, \u00bfqu\u00e9 era lo que m\u00e1s te atra\u00eda?'
      : 'Tell me \u2014 when the project still called to you, what was it that pulled you most?';
    post({ action: 'cftConvTurn', sessionId: _session, requestingMemberId: _memberId, projectId: '', systemPrompt: fireSys,
      conversationHistory: [{ role: 'user', content: '(The member arrives from the Talent Time fire reading: devotion ' + n + '/5, choke: no pull.)' }] })
    .then(function(d) {
      var reply = (d && d.reply) ? d.reply : ((d && d.content && d.content[0]) ? d.content[0].text : '');
      if (!reply) reply = fallbackQ;
      pwsAppendBubble(reply, 'docb');
      _docbHistory.push({ role: 'assistant', content: reply });
    }).catch(function() {
      pwsAppendBubble(fallbackQ, 'docb');
      _docbHistory.push({ role: 'assistant', content: fallbackQ });
    });
  }

  // v97 UNIFICATION: mint door inside the serves picker. Ported from
  // /todos tdMintContribution (v28). Calls pwsAppendStation (Games URL,
  // idempotent -- duplicate text returns existing, never twins), adopts
  // the contribution locally, links the slot by cid, saves the day, and
  // re-renders so the new dot appears on the Contributions tile at once.
  window.pwsServesMint = function pwsServesMint(fsIdx) {
    var inp = document.getElementById('pwsServesMintInput' + fsIdx);
    var btn = document.getElementById('pwsServesMintBtn' + fsIdx);
    var st  = document.getElementById('pwsServesMintStatus' + fsIdx);
    if (!inp) return;
    var text = (inp.value || '').replace(/^\s+|\s+$/g, '');
    if (!text) { if (st) st.textContent = _lang === 'es' ? 'Escribe un nombre primero.' : 'Write a name first.'; return; }
    if (btn) btn.disabled = true;
    if (st)  st.textContent = _lang === 'es' ? 'Declarando\u2026' : 'Declaring\u2026';
    fetch(GAMES_URL, { method: 'POST', body: JSON.stringify({ action: 'pwsAppendStation', memberId: _memberId, text: text }) })
      .then(function(r){ return r.json(); })
      .then(function(d) {
        if (!d || !d.success || !d.contribution || !d.contribution.cid) {
          if (st)  st.textContent = _lang === 'es' ? 'No se pudo guardar. Intenta de nuevo.' : 'Could not save. Try again.';
          if (btn) btn.disabled = false;
          return;
        }
        var c = d.contribution;
        if (!_obsData) _obsData = { confirmedObs: [] };
        if (!_obsData.confirmedObs) _obsData.confirmedObs = [];
        var already = false;
        _obsData.confirmedObs.forEach(function(ob) { if (ob && ob.cid === c.cid) already = true; });
        if (!already) _obsData.confirmedObs.push(c);
        var slot = (_dayData && _dayData.finalSchedule) ? _dayData.finalSchedule[fsIdx] : null;
        if (slot) {
          slot.contributionCid = c.cid;
          delete slot.contributionId;
          delete slot.lawTag;
          pwsSaveDaySchedule();
        }
        pwsRenderStationTile();
        pwsRenderToolsTile();
        pwsRenderDayTile();
      })
      .catch(function() {
        if (st)  st.textContent = _lang === 'es' ? 'Error de conexi\u00f3n.' : 'Connection error.';
        if (btn) btn.disabled = false;
      });
  };

  // ── v98 EQUIPPING STANDARD — the wall, cloned from todos_v31 ─────────
  // The Racked Promise on the stage: every drawer shows what the window
  // owns -- Shelf, Links, Contacts, Alarms -- reading the SAME
  // window_config keys the workshop writes. Rack here, see it there.
  // Sticky Config law: every act below writes into the window's own
  // config. Bytes live in Drive (PWSFiles.gs, Main 223); the sheet racks
  // only {fileId, name, viewUrl}.

  var PWS_EQ_ROW  = 'display:flex;align-items:center;gap:8px;margin-top:6px;background:rgba(240,230,204,0.04);border:1px solid rgba(200,168,75,0.2);border-radius:4px;padding:8px 10px;max-width:100%;box-sizing:border-box;'; /* v91_15: the row can never outgrow the drawer */
  var PWS_EQ_HDR  = 'font-family:Cinzel,serif;font-size:13px;letter-spacing:0.12em;text-transform:uppercase;color:rgba(200,168,75,0.7);margin-top:14px;';
  var PWS_EQ_A    = 'flex:1;min-width:0;color:#c8a84b;font-family:Cormorant Garamond,serif;font-size:18px;text-decoration:none;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;min-height:28px;display:flex;align-items:center;'; /* v91_15 THE VISIBLE HAND: without min-width:0 a flex child refuses to shrink below its content, so a long URL shoved the whole row -- and the \u2715 -- off the right edge */
  var PWS_EQ_TXT  = 'flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;color:#f0e6cc;font-family:Cormorant Garamond,serif;font-size:18px;'; /* v91_15: same shrink law */
