        useAppendBubble(_lang === 'es' ? 'Chat guardado. \u00bfSeguimos?' : 'Chat saved. Ready to continue?', 'docb');
        if (btn) { btn.innerHTML = '<span class="en">&#10003; Saved</span><span class="es">&#10003; Guardado</span>'; }
