    for (var ri = 0; ri < rows.length; ri++) {
      var r = rows[ri]; if (!r || !r.name || !r.phone) continue;
      _useTool.contacts.push({ name: r.name, phone: r.phone, extraLink: r.extraLink || '' });
    }
    pwsPersistContactsSave_();
    var listDiv = document.getElementById('pwsContactsList');
    if (listDiv) pwsRenderContactsList(listDiv);
